from pathlib import Path
import subprocess as sp,json,random,shutil,statistics,hashlib
p=Path(__file__).parent;variants=['baseline','control','preload','common','common_simple','equal'];rows=[];builds=[]
for v in variants:
 shutil.copyfile(p/(('baseline'if v=='control'else v)+'.hpp'),p/'active.hpp');cmd=['taskset','-c','0','/usr/bin/g++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DHEADER="'+str(p/'active.hpp')+'"',str(p/'bench.cpp'),'-o',str(p/v)];b=sp.run(cmd,capture_output=True,text=True);assert not b.returncode,b.stderr;builds.append({'variant':v,'cmd':cmd,'binary_sha256':hashlib.sha256((p/v).read_bytes()).hexdigest()})
for rep in range(13):
 for n in [32,32768,500000]:
  for shape in range(13):
   order=variants.copy();random.Random(rep*817+n+shape).shuffle(order);checks=[]
   for v in order:
    shutil.copyfile(p/v,p/'run-active');(p/'run-active').chmod(0o755);a,b=map(int,sp.check_output(['taskset','-c','0',str(p/'run-active'),str(n),str(shape)],text=True).split());checks.append(b);rows.append({'variant':v,'rep':rep,'n':n,'shape':shape,'ns':a,'checksum':b})
   assert len(set(checks))==1
 (p/'running.json').write_text(json.dumps(rows));print(rep,flush=True)
summary=[]
for n in [32,32768,500000]:
 for shape in range(13):
  med={v:statistics.median(x['ns']for x in rows if x['n']==n and x['shape']==shape and x['variant']==v)for v in variants};summary.append({'n':n,'shape':shape,'median_ns':med,'ratio':{v:med[v]/med['baseline']for v in variants}})
