std::uint64_t expected=0;for(auto op:ops)expected+=op.type?ref.same(op.a,op.b):ref.merge(op.a,op.b);const auto start=now();std::uint64_t sum=0;for(auto op:ops)sum+=op.type?uf.same(op.a,op.b):uf.merge(op.a,op.b);const auto elapsed=now()-start;if(sum!=expected||uf.component_count()!=ref.components)return 4;for(int i=0;i<n;i+=std::max(1,n/1000))if(uf.root(i)!=ref.root(i)||uf.size(i)!=ref.s[ref.root(i)])return 5;std::printf("%llu %llu\n",(unsigned long long)elapsed,(unsigned long long)sum);}

